using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class CollisionSurvey {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B4_DeskAndCollision/"));static float[] V(Vector3 p)=>new[]{p.x,p.y,p.z};
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");string original=s.path;var summary=new List<object>();try{foreach(string f in new[]{"B5","B4"}){s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+f+"_Circular.unity");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).ToArray();var cc=ts.Select(t=>t.GetComponent<CharacterController>()).Single(c=>c);var rows=new List<object>();foreach(var t in ts){var cs=t.GetComponents<Collider>();if(cs.Length==0||!t.gameObject.activeInHierarchy)continue;var mf=t.GetComponent<MeshFilter>();string asset=mf&&mf.sharedMesh?AssetDatabase.GetAssetPath(mf.sharedMesh):"";rows.Add(new{name=t.name,id=GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),asset,p=V(t.position),e=V(t.eulerAngles),cols=cs.Select(c=>new{type=c.GetType().Name,enabled=c.enabled,trigger=c.isTrigger,center=V(c.bounds.center),size=V(c.bounds.size),localCenter=c is BoxCollider b?V(b.center):null,localSize=c is BoxCollider bb?V(bb.size):null})});}File.WriteAllText(H+f+"_colliders.json",JsonConvert.SerializeObject(rows,Formatting.Indented));summary.Add(new{floor=f,objects=rows.Count,player=new{cc.radius,cc.height,center=V(cc.center),cc.stepOffset,cc.skinWidth}});}}finally{EditorSceneManager.OpenScene(original);}return summary;}
}
